// devolve os dados do lead recem-criado para quem chamou este workflow via Execute Workflow -
// sem isso, o retorno seria a resposta da API do Resend (ultimo no do fluxo), nao o lead_id.
// 21/09/2026: inclui email_boasvindas_enviado (false quando o Resend falhou, ex.: cota diaria).
const resend = $('06_email_boasvindas').first().json || {};
const enviado = !!resend.id && !resend.error;
return { json: { ...$('05_extrai_lead_id').item.json, email_boasvindas_enviado: enviado, email_boasvindas_erro: enviado ? '' : String((resend.error && (resend.error.message || resend.error)) || resend.message || 'falha no envio') } };

// Aditivo (21/09/2026): quando origem === 'Lead site institucional', vincula a fonte (source_id) do RD Station ao deal recem-criado.
// Qualquer outra origem passa direto, sem chamada extra. Erros aqui nao interrompem o fluxo (onError = continue).
const items = $input.all();
const origem = String($('01_execute_workflow_trigger').first().json.origem || '').trim();
if (origem !== 'Lead site institucional') return items;
const token = $('02_token_rdstation').first().json.access_token;
const base = 'https://api.rd.services/crm/v2';
const H = { Authorization: 'Bearer ' + token, Accept: 'application/json', 'Content-Type': 'application/json' };
const dealId = $('04_criar_negociacao').first().json.data && $('04_criar_negociacao').first().json.data.id;
if (!dealId) return items;
let sourceId = '6ab0f57e1e0b5b0023261503'; // fonte "Lead site institucional" criada em 21/09/2026
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: base + '/sources?limit=100', headers: H, json: true });
  const norm = x => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
  const hit = ((r && r.data) || []).find(f => norm(f.name) === norm('Lead site institucional'));
  if (hit && hit.id) sourceId = hit.id;
} catch (e) { /* mantem o id fixo */ }
const put = await this.helpers.httpRequest({ method: 'PUT', url: base + '/deals/' + dealId, headers: H, body: { data: { source_id: sourceId } }, returnFullResponse: true, ignoreHttpStatusErrors: true, json: true });
return items.map(it => ({ json: { ...it.json, fonte_site_institucional: { deal_id: dealId, source_id: sourceId, put_status: put.statusCode } } }));
